  const r = await notifyRunDone(summary, { env: { BULWARK_SLACK_WEBHOOK_URL: 'https://hooks.slack.test/x' }, scores, log: (m) => logs.push(m) });
  assert.deepEqual(r.sent, []);
  assert.ok(logs.some((l) => /not sending during tests/.test(l)));
});

