// Runs the workflows' actions/github-script bodies against a mocked GitHub API.
// Usage: node gh-script-harness.cjs <scratch dir>  (cwd = repo with .bulwark/ci/scorecard.md)
const fs = require('fs');
const path = require('path');
const dir = process.argv[2];
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
const run = (file, globals) => new AsyncFunction(...Object.keys(globals), fs.readFileSync(path.join(dir, file), 'utf8'))(...Object.values(globals));

function mockGithub(existing) {
  const calls = [];
  const comments = [...existing];
  const rest = {
    issues: {
      listComments: async () => ({ data: comments }),
      createComment: async (a) => (calls.push(['createComment', a.issue_number, a.body.slice(0, 40)]), { data: {} }),
      updateComment: async (a) => (calls.push(['updateComment', a.comment_id, a.body.slice(0, 40)]), { data: {} }),
    },
    reactions: { createForIssueComment: async (a) => (calls.push(['reaction', a.comment_id, a.content]), {}) },
    pulls: { get: async () => ({ data: { head: { sha: 'abc123', ref: 'feature/x', repo: { full_name: 'o/r' } }, base: { ref: 'main' } } }) },
  };
  return { calls, github: { rest, paginate: async (fn, args) => (await fn(args)).data } };
}

(async () => {
  const context = { repo: { owner: 'o', repo: 'r' }, payload: { pull_request: { number: 7 }, comment: { id: 99 } }, issue: { number: 7 } };
  // 1. No previous comment → create.
  let m = mockGithub([{ id: 1, user: { type: 'User' }, body: 'hi' }]);
  await run('sticky.js', { require, github: m.github, context });
  console.log('sticky, first run :', JSON.stringify(m.calls));
  // 2. Our bot comment exists → update it (a human quoting the marker is ignored).
  m = mockGithub([{ id: 2, user: { type: 'User' }, body: '<!-- bulwark-ci-scorecard --> quoted' }, { id: 3, user: { type: 'Bot' }, body: '<!-- bulwark-ci-scorecard -->\nold' }]);
  await run('sticky.js', { require, github: m.github, context });
  console.log('sticky, second run:', JSON.stringify(m.calls));
  // 3. ChatOps lookup + reply.
  m = mockGithub([]);
  const outputs = {};
  await run('lookup.js', { require, github: m.github, context, core: { setOutput: (k, v) => (outputs[k] = v) } });
  console.log('chatops lookup    :', JSON.stringify(m.calls), JSON.stringify(outputs));
  m = mockGithub([]);
  await run('reply.js', { require, github: m.github, context });
  console.log('chatops reply     :', JSON.stringify(m.calls));
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

